import React from "react";
import { motion } from "framer-motion";
import { TESTIMONIALS } from "./Content";
import { Quote, Star } from "lucide-react";

export default function Testimonials() {
  const items = [...TESTIMONIALS, ...TESTIMONIALS];

  return (
    <section id="reviews" className="relative py-20 md:py-28 overflow-hidden" style={{ background: "#faf8f5" }}>
      <div className="max-w-7xl mx-auto px-6 md:px-12 lg:px-32">
        <motion.div
          className="mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
        >
          <div className="overline mb-6 font-bold tracking-[0.4em]">Testimonials</div>
          <h2 style={{ fontSize: "clamp(40px, 5vw, 64px)", lineHeight: 1.05, color: "#1a080a", fontFamily: "Outfit, sans-serif", fontWeight: 800, maxWidth: 700 }}>
            What decorators across India <span style={{ color: "#d4af37", fontWeight: 800 }}>keep saying</span>.
          </h2>
        </motion.div>

        <div className="relative">
          <motion.div
            className="absolute left-0 top-0 bottom-0 w-32 z-10 pointer-events-none"
            style={{ background: "linear-gradient(to right, #faf8f5, transparent)" }}
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
            viewport={{ once: true }}
          />
          <motion.div
            className="absolute right-0 top-0 bottom-0 w-32 z-10 pointer-events-none"
            style={{ background: "linear-gradient(to left, #faf8f5, transparent)" }}
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
            viewport={{ once: true }}
          />

          <motion.div
            className="marquee py-2"
            whileHover={{ animationPlayState: "paused" }}
          >
            {items.map((t, i) => (
              <motion.article
                key={i}
                className="p-7 md:p-9 flex-shrink-0"
                style={{ width: 480, background: "#faf8f5", border: "1px solid rgba(0,0,0,0.06)", boxShadow: "0 4px 24px rgba(0,0,0,0.04)" }}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: i * 0.05, duration: 0.5 }}
                whileHover={{
                  y: -5,
                  boxShadow: "0 16px 48px rgba(0,0,0,0.08)",
                  transition: { duration: 0.3 }
                }}
              >
                <Quote size={28} strokeWidth={1.4} style={{ color: "#d4af37", marginBottom: 16 }} />
                <p className="serif" style={{ color: "#1a080a", fontSize: 18, lineHeight: 1.5, fontWeight: 400, minHeight: 100 }}>"{t.quote}"</p>
                <div className="mt-5 flex items-center justify-between">
                  <div>
                    <motion.div
                      style={{ color: "#1a080a", fontWeight: 600, letterSpacing: "0.02em" }}
                      whileHover={{ color: "#d4af37" }}
                    >
                      {t.name}
                    </motion.div>
                    <div className="text-xs mt-1" style={{ color: "rgba(26,8,10,0.6)" }}>{t.role} - {t.city}</div>
                  </div>
                  <motion.div
                    className="flex items-center gap-0.5"
                    whileHover={{ scale: 1.1 }}
                  >
                    {[...Array(5)].map((_, idx) => (
                      <motion.div
                        key={idx}
                        initial={{ opacity: 0, scale: 0 }}
                        whileInView={{ opacity: 1, scale: 1 }}
                        viewport={{ once: true }}
                        transition={{ delay: idx * 0.05 }}
                      >
                        <Star size={14} fill="#d4af37" color="#d4af37" strokeWidth={0} />
                      </motion.div>
                    ))}
                  </motion.div>
                </div>
                <motion.div
                  className="mt-4 text-[10px] tracking-[0.22em] uppercase font-semibold"
                  style={{ color: "#d4af37" }}
                  whileHover={{ scale: 1.05 }}
                >
                  Verified Customer
                </motion.div>
              </motion.article>
            ))}
          </motion.div>
        </div>
      </div>
    </section>
  );
}
